  function routeLinks(root, target) {
    const hosts = ['xn--80awro.xn--p1ai', 'хасл.рф', 'haslestore.com', 'www.haslestore.com'];
    const rewrite = value => {
      try {
        const u = new URL(value, target);
        if (['sale.xn--80awro.xn--p1ai','sale.haslestore.com'].includes(u.hostname)) {
          u.host=new URL(target).hostname.includes('haslestore.com')?'sale.haslestore.com':'sale.xn--80awro.xn--p1ai';return u.href;
        }
        if (hosts.includes(u.hostname)) {
          u.host = new URL(target).host;
          u.pathname = u.pathname.replace(/^\/(?:krossovki|sneakers)(?=\/|$)/, u.host.includes('haslestore.com') ? '/sneakers' : '/krossovki');
          if (u.searchParams.has('url')) u.searchParams.set('url', rewrite(u.searchParams.get('url')));
          return u.href;
        }
      } catch {}
      return value;
    };
    // Store video files are mirrored under /storage; use the selected storefront's CSP-allowed origin.
    root.querySelectorAll('video[src],video source[src]').forEach(el=>{
      try{const u=new URL(el.getAttribute('src'),target);if(hosts.includes(u.hostname)&&u.pathname.startsWith('/storage/import_files/')){u.host=new URL(target).host;el.setAttribute('src',u.href);}}catch{}
    });
    root.dataset.siteOrigin = target;
    root.dataset.catalogPath = new URL(target).host.includes('haslestore.com') ? '/sneakers' : '/krossovki';
    root.querySelectorAll('a[href],area[href],form[action]').forEach(el => ['href','action'].forEach(attr => {
      const value = el.getAttribute(attr);
      if(value && !value.startsWith('#') && !(el.closest('[data-site-element]') && /^\/?(?:[a-zA-Z0-9_-]+\/)*[a-zA-Z0-9_-]+\.html(?:#[a-zA-Z][\w-]*)?$/.test(value))) el.setAttribute(attr, rewrite(value));
    }));
    // The universal HTML changes storefront links at runtime; keep the same
    // product/article URLs in its already embedded JSON-LD. Explicit page
    // canonical URLs and image URLs are independent and remain authoritative.
    for(const script of root.querySelectorAll('script[data-site-schema="auto"]')){
      try{
        const data=JSON.parse(script.textContent);
        const visit=value=>{
          if(!value||typeof value!=='object')return;
          const types=[].concat(value['@type']||[]),fixedUrl=types.some(t=>['WebPage','CollectionPage','FAQPage','ImageObject'].includes(t));
          for(const [key,item] of Object.entries(value)){
            if(key==='url'&&typeof item==='string'&&!fixedUrl)value[key]=rewrite(item);
            else if(item&&typeof item==='object')visit(item);
          }
        };
        visit(data);script.textContent=JSON.stringify(data).replace(/</g,'\\u003c').replace(/>/g,'\\u003e').replace(/&/g,'\\u0026').replace(/\u2028/g,'\\u2028').replace(/\u2029/g,'\\u2029');
      }catch{/* An unrelated or damaged script must not break storefront links. */}
    }
  }

